/**
 * @name Path traversal in archive extraction
 * @description Extracting archives without validating paths can allow path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-archive
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      // Look for tarfile/zipfile extractions
      (
        call = API::moduleImport("tarfile").getMember("open").getACall() or
        call = API::moduleImport("zipfile").getMember("ZipFile").getACall()
      ) and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["extract", "extractall"] and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where 
  PathTraversalFlow::flowPath(source, sink) and
  not source.getNode().getLocation().getFile().getRelativePath().matches("%/_vendor/%")
select sink.getNode(), source, sink, "Archive extraction without path validation from $@.", source.getNode(), "archive"
